	const rootRecord = byId.get(rootNode.id) || {};
	const rootX = Number(rootRecord.x ?? rootNode.x) || 0;
	const rootY = Number(rootRecord.y ?? rootNode.y) || 0;
	const ids = new Set(branchNodes.map((item) => item.id));
